def tol(key, label, w):
    """허용 차이(포장 표시 기준량 w g당)"""
    if key == 'kcal':
        return max(5 + 0.005 * w, 0.02 * label)
    if key == 'na':
        return max(20, 0.10 * label) + 0.005 * w
    return max(1.0, 0.05 * label) + 0.00005 * w


CALC_TOL = 10.5  # ③ 표시 열량과 계산 열량의 허용 차이(kcal)


def calc_kcal(s):
    """표시값으로 계산한 열량: (탄수화물-식이섬유-당알코올)x4 + 식이섬유x2 + 당알코올x2.4 + 단백질x4 + 지방x9"""
    fi = s.get('fi', 0); pol = s.get('polyol', 0)
    return (s['c'] - fi - pol) * 4 + fi * 2 + pol * 2.4 + s.get('p', 0) * 4 + s['f'] * 9


